      "name": "test_neg1_iff_same_row_or_col",
      "source": "def test_neg1_iff_same_row_or_col(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = lines[1:]
    sr = sc = tr = tc = -1
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                sr, sc = i, j
            elif grid[i][j] == 'T':
                tr, tc = i, j
    out = run(x).strip()
    if sr == tr or sc == tc:
