    },
    {
      "name": "test_zero_iff_disconnected",
      "source": "def test_zero_iff_disconnected(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = lines[1:]
    # Build graph adjacency sets
    row_to_cells = [[] for _ in range(H)]
    col_to_cells = [[] for _ in range(W)]
    cells = []
    idx_of = {}
    for i in range(H):
        for j in range(W):
            if grid[i][j] != '.':
                idx = len(cells)
                idx_of[(i, j)] = idx
                cells.append((i, j))
                row_to_cells[i].append(idx)
                col_to_cells[j].append(idx)
    n = len(cells)
    adj = [[] for _ in range(n)]
    for i in range(H):
        lst = row_to_cells[i]
        for a in lst:
            for b in lst:
                if a != b:
                    adj[a].append(b)
    for j in range(W):
        lst = col_to_cells[j]
        for a in lst:
            for b in lst:
                if a != b:
                    adj[a].append(b)
    # Find S and T indices
    S_idx = T_idx = -1
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                S_idx = idx_of[(i, j)]
            elif grid[i][j] == 'T':
                T_idx = idx_of[(i, j)]
    # BFS
    visited = [False] * n
    stack = [S_idx]
    visited[S_idx] = True
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                stack.append(v)
    out = run(x).strip()
    reachable = visited[T_idx]
    if reachable:
        assert out != '0', f"S and T are connected, expected non‑zero, got 0"
    else:
        assert out == '0', f"S and T are disconnected, expected 0, got {out}""
    },
    {
      "name": "test_symmetric_swap_st",
      "source": "def test_symmetric_swap_st(run, x):
