def test_bounds(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    o_count = sum(row.count('o') for row in lines[1:])
    out = run(x).strip()
    if out == '-1':
        return
    val = int(out)
    assert val >= 0, f"Removal count must be nonnegative, got {val}"
    assert val <= o_count, f"Removal count {val} exceeds number of 'o' cells {o_count}"

def test_neg1_iff_same_row_or_col(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = lines[1:]
    sr = sc = tr = tc = -1
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                sr, sc = i, j
            elif grid[i][j] == 'T':
                tr, tc = i, j
    out = run(x).strip()
    if sr == tr or sc == tc:
        assert out == '-1', f"S and T share row or column, expected -1, got {out}"
    else:
        assert out != '-1', f"S and T do not share row or column, but got -1"

def test_zero_iff_disconnected(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = lines[1:]
    # Build graph adjacency sets
    row_to_cells = [[] for _ in range(H)]
    col_to_cells = [[] for _ in range(W)]
    cells = []
    idx_of = {}
    for i in range(H):
        for j in range(W):
            if grid[i][j] != '.':
                idx = len(cells)
                idx_of[(i, j)] = idx
                cells.append((i, j))
                row_to_cells[i].append(idx)
                col_to_cells[j].append(idx)
    n = len(cells)
    adj = [[] for _ in range(n)]
    for i in range(H):
        lst = row_to_cells[i]
        for a in lst:
            for b in lst:
                if a != b:
                    adj[a].append(b)
    for j in range(W):
        lst = col_to_cells[j]
        for a in lst:
            for b in lst:
                if a != b:
                    adj[a].append(b)
    # Find S and T indices
    S_idx = T_idx = -1
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                S_idx = idx_of[(i, j)]
            elif grid[i][j] == 'T':
                T_idx = idx_of[(i, j)]
    # BFS
    visited = [False] * n
    stack = [S_idx]
    visited[S_idx] = True
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                stack.append(v)
    out = run(x).strip()
    reachable = visited[T_idx]
    if reachable:
        assert out != '0', f"S and T are connected, expected non‑zero, got 0"
    else:
        assert out == '0', f"S and T are disconnected, expected 0, got {out}"

def test_symmetric_swap_st(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = [list(row) for row in lines[1:]]
    # Swap S and T
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                grid[i][j] = 'T'
            elif grid[i][j] == 'T':
                grid[i][j] = 'S'
    swapped_input = f"{H} {W}\n" + '\n'.join(''.join(row) for row in grid)
    out1 = run(x).strip()
    out2 = run(swapped_input).strip()
    assert out1 == out2, f"Swapping S and T changed output: {out1} vs {out2}"

def test_row_permutation(run, x):
    lines = x.strip().split('\n')
