def test_transpose(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = lines[1:]
    # Transpose
    transposed = [''.join(grid[i][j] for i in range(H)) for j in range(W)]
    transposed_input = f"{W} {H}\n" + '\n'.join(transposed)
    out1 = run(x).strip()
    out2 = run(transposed_input).strip()
    assert out1 == out2, f"Transposing grid changed output: {out1} vs {out2}"

def test_isolated_leaf_addition(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = [list(row) for row in lines[1:]]
    # Find a '.' cell whose row and column contain no leaf at all
    added = False
    for i in range(H):
        row_has_leaf = any(cell in 'SoT' for cell in grid[i])
        if row_has_leaf:
            continue
        for j in range(W):
            if grid[i][j] != '.':
                continue
            col_has_leaf = any(grid[r][j] in 'SoT' for r in range(H))
            if not col_has_leaf:
                # Change to 'o'
                grid[i][j] = 'o'
                added = True
                break
        if added:
            break
    if not added:
        # No such cell, test passes trivially
        return
    modified_input = f"{H} {W}\n" + '\n'.join(''.join(row) for row in grid)
    out1 = run(x).strip()
    out2 = run(modified_input).strip()
    assert out1 == out2, f"Adding isolated leaf changed output: {out1} vs {out2}"

def test_remove_all_o(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = [list(row) for row in lines[1:]]
    # Change every 'o' to '.'
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'o':
                grid[i][j] = '.'
    modified_input = f"{H} {W}\n" + '\n'.join(''.join(row) for row in grid)
    out = run(modified_input).strip()
    # Determine if S and T share row or column in modified grid
    sr = sc = tr = tc = -1
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                sr, sc = i, j
            elif grid[i][j] == 'T':
                tr, tc = i, j
    if sr == tr or sc == tc:
        assert out == '-1', f"After removing all 'o', S and T share row/col, expected -1, got {out}"
    else:
        assert out == '0', f"After removing all 'o', S and T not share row/col, expected 0, got {out}"

