      "name": "test_digit_sum_correctness",
      "source": "def test_digit_sum_correctness(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = int(lines[1])
    out = run(x).strip()
    if out != "-1":
        b = int(out)
        # Compute digit sum in base b
        temp = n
        total = 0
        while temp > 0:
            total += temp % b
            temp //= b
        assert total == s, f"Digit sum in base {b} is {total}, expected {s}""
    },
    {
      "name": "test_minimality_via_divisors",
      "source": "def test_minimality_via_divisors(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = int(lines[1])
    out = run(x).strip()
    if out != "-1" and s != n:
        b = int(out)
        diff = n - s
        # Check only divisors d where d+1 < b.
        # To keep it fast, limit to divisors ≤ 10^6.
        # This is a weakening, but still catches many mistakes.
        if diff == 0:
            return
        max_check = min(10**6, int(diff**0.5))
        for d in range(1, max_check + 1):
            if diff % d == 0:
                for cand in [d, diff // d]:
                    base = cand + 1
                    if base < b and base >= 2:
                        # compute digit sum in base
                        temp = n
                        total = 0
                        while temp > 0:
                            total += temp % base
                            temp //= base
                        if total == s:
                            assert False, f"Found smaller base {base} that also gives digit sum {s}""
    },
    {
      "name": "test_nonexistence_via_divisors",
