tests_src:
def test_valid_output(run, x):
    # Intent: output must be a single integer, either -1 or >=2
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False, f'Output not an integer: {out}'
    if val != -1:
        assert val >= 2, f'Output {val} is not -1 and is less than 2'

def test_s_greater_n(run, x):
    # If s > n, output must be -1
    n_str, s_str = x.strip().split()
    n = int(n_str); s = int(s_str)
    if s > n:
        out = run(x).strip()
        val = int(out)
        assert val == -1, f's > n ({s} > {n}) but output is {val}, not -1'

def test_s_equal_n(run, x):
    # If s == n, output must be n+1
    n_str, s_str = x.strip().split()
    n = int(n_str); s = int(s_str)
    if s == n:
        out = run(x).strip()
        val = int(out)
        assert val == n + 1, f's == n ({s}) but output is {val}, not n+1'

def test_output_bounds(run, x):
    # Output b must satisfy 2 <= b <= n+1
    n_str, _ = x.strip().split()
    n = int(n_str)
    out = run(x).strip()
    b = int(out)
    if b != -1:
        assert 2 <= b <= n + 1, f'Output base b={b} outside [2, n+1] where n={n}'

def test_output_bounds_s_less_n(run, x):
    # If s < n and output is b, then b <= n
    n_str, s_str = x.strip().split()
    n = int(n_str); s = int(s_str)
    if s < n:
        out = run(x).strip()
        b = int(out)
        if b != -1:
            assert b <= n, f's < n ({s} < {n}) but output b={b} > n'

def test_certificate(run, x):
    # If output is b, compute digit sum of n in base b and verify equals s
    n_str, s_str = x.strip().split()
    n = int(n_str); s = int(s_str)
    out = run(x).strip()
    b = int(out)
    if b != -1:
        # compute digit sum
        temp = n
        total = 0
        while temp > 0:
            total += temp % b
            temp //= b
        if n < b:
            total = n  # definition
        assert total == s, f'Digit sum of n={n} in base b={b} is {total}, not s={s}'

def test_minimality_small_b(run, x):
    # For each b' from 2 up to min(b-1, sqrt(n)), verify digit sum != s
    n_str, s_str = x.strip().split()
    n = int(n_str); s = int(s_str)
    out = run(x).strip()
    b = int(out)
    if b != -1 and b > 2:
        import math
        limit = min(b - 1, int(math.isqrt(n)))  # floor(sqrt(n))
        for bp in range(2, limit + 1):
            temp = n
            total = 0
            while temp > 0:
                total += temp % bp
                temp //= bp
            if n < bp:
                total = n
            if total == s:
                assert False, f'Found smaller base bp={bp} with digit sum s'

def test_minimality_large_b_divisors(run, x):
    # For divisors d of l = n-s, check b' = d+1 > sqrt(n) and b' < b, verify digit sum != s
    n_str, s_str = x.strip().split()
    n = int(n_str); s = int(s_str)
    out = run(x).strip()
    b = int(out)
    if b != -1:
        import math
        l = n - s
        sqrt_n = int(math.isqrt(n))
        # enumerate divisors up to sqrt(l)
        for d in range(1, int(math.isqrt(l)) + 1):
            if l % d == 0:
                for d_val in (d, l // d):
                    bp = d_val + 1
                    if bp > sqrt_n and bp < b:
                        temp = n
                        total = 0
                        while temp > 0:
                            total += temp % bp
                            temp //= bp
                        if n < bp:
                            total = n
                        if total == s:
                            assert False, f'Found smaller base bp={bp} (from divisor d={d_val}) with digit sum s'

def test_nonexistence_small_b(run, x):
    # If output is -1, check all b' from 2 to sqrt(n) for digit sum != s
    n_str, s_str = x.strip().split()
    n = int(n_str); s = int(s_str)
    out = run(x).strip()
    val = int(out)
    if val == -1:
        import math
        limit = int(math.isqrt(n))
        for bp in range(2, limit + 1):
            temp = n
            total = 0
            while temp > 0:
                total += temp % bp
                temp //= bp
            if n < bp:
                total = n
            if total == s:
                assert False, f'Base bp={bp} exists with digit sum s, but output is -1'

def test_nonexistence_large_b_divisors(run, x):
    # If output is -1, for divisors d of l = n-s with b' = d+1 > sqrt(n), check digit sum != s
    n_str, s_str = x.strip().split()
    n = int(n_str); s = int(s_str)
    out = run(x).strip()
    val = int(out)
    if val == -1:
        import math
        l = n - s
        sqrt_n = int(math.isqrt(n))
        # enumerate divisors
        for d in range(1, int(math.isqrt(l)) + 1):
            if l % d == 0:
                for d_val in (d, l // d):
                    bp = d_val + 1
                    if bp > sqrt_n:
                        temp = n
                        total = 0
                        while temp > 0:
                            total += temp % bp
                            temp //= bp
                        if n < bp:
                            total = n
                        if total == s:
                            assert False, f'Base bp={bp} (from divisor d={d_val}) exists with digit sum s, but output is -1'

