def test_feasibility(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    n, m, k = map(int, lines[0].split())
    cities_in = [False] * (n + 1)
    cities_out = [False] * (n + 1)
    for line in lines[1:1 + m]:
        if not line:
            continue
        d, f, t, c = map(int, line.split())
        if t == 0:
            cities_in[f] = True
        else:  # f == 0
            cities_out[t] = True
    feasible = True
    for i in range(1, n + 1):
        if not (cities_in[i] and cities_out[i]):
            feasible = False
            break
    if not feasible:
        out = run(x).strip()
        assert out == '-1', f'Expected -1 for missing flight, got {out}'
        return
    # compute earliest incoming day per city, latest outgoing day per city
    earliest = [10**9] * (n + 1)
    latest = [0] * (n + 1)
    for line in lines[1:1 + m]:
        if not line:
            continue
        d, f, t, c = map(int, line.split())
        if t == 0:
            if d < earliest[f]:
                earliest[f] = d
        else:
            if d > latest[t]:
                latest[t] = d
    L = max(earliest[1:])
    R = min(latest[1:])
    if R - L - 1 < k:
        out = run(x).strip()
        assert out == '-1', f'Expected -1 because window too small, got {out}'
    else:
        out = run(x).strip()
        assert out != '-1', 'Expected feasible schedule, got -1'


def test_lower_bound(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    n, m, k = map(int, lines[0].split())
    min_in = [10**9] * (n + 1)
    min_out = [10**9] * (n + 1)
    for line in lines[1:1 + m]:
        if not line:
            continue
        d, f, t, c = map(int, line.split())
        if t == 0:
            if c < min_in[f]:
                min_in[f] = c
        else:
            if c < min_out[t]:
                min_out[t] = c
    lb = 0
    for i in range(1, n + 1):
        if min_in[i] == 10**9 or min_out[i] == 10**9:
            lb = -1
            break
        lb += min_in[i] + min_out[i]
    out = run(x).strip()
    if out != '-1':
        C = int(out)
        if lb != -1:
            assert C >= lb, f'Output {C} < lower bound {lb}'


def test_upper_bound_simple(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    n, m, k = map(int, lines[0].split())
    # compute earliest incoming day per city, latest outgoing day per city
    earliest = [10**9] * (n + 1)
    latest = [0] * (n + 1)
    for line in lines[1:1 + m]:
        if not line:
            continue
        d, f, t, c = map(int, line.split())
        if t == 0:
            if d < earliest[f]:
                earliest[f] = d
        else:
            if d > latest[t]:
                latest[t] = d
    L = max(earliest[1:])
    R = min(latest[1:])
    if R - L - 1 < k:
        return  # infeasible, no bound needed
    # compute cheapest incoming with day <= L, cheapest outgoing with day >= R
    best_in = [10**9] * (n + 1)
    best_out = [10**9] * (n + 1)
    for line in lines[1:1 + m]:
        if not line:
            continue
        d, f, t, c = map(int, line.split())
        if t == 0 and d <= L:
            if c < best_in[f]:
                best_in[f] = c
        elif f == 0 and d >= R:
            if c < best_out[t]:
                best_out[t] = c
    ub = 0
    for i in range(1, n + 1):
        if best_in[i] == 10**9 or best_out[i] == 10**9:
            ub = -1
            break
        ub += best_in[i] + best_out[i]
    out = run(x).strip()
    if out != '-1' and ub != -1:
        C = int(out)
        assert C <= ub, f'Output {C} > simple upper bound {ub}'


