def test_output_type(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    # must be a non-negative integer string
    assert out.isdigit() and int(out) >= 0

def test_minus_one_implies_gcd_greater_than_one(run, x):
    import math
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return  # malformed, but test will fail elsewhere
    a = list(map(int, lines[1].split()))
    if not a:
        return
    g = a[0]
    for v in a[1:]:
        g = math.gcd(g, v)
    out = run(x).strip()
    if out == '-1':
        assert g > 1

def test_not_minus_one_implies_gcd_one(run, x):
    import math
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    if not a:
        return
    g = a[0]
    for v in a[1:]:
        g = math.gcd(g, v)
    out = run(x).strip()
    if out != '-1':
        # out must be a non-negative integer per test 1
        assert out.isdigit() and int(out) >= 0
        assert g == 1

def test_one_present_equals_count_non_one(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    if 1 in a:
        non_one = sum(1 for v in a if v != 1)
        out = run(x).strip()
        if out != '-1':
            assert int(out) == non_one

def test_no_one_bounds(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    if 1 in a:
        return  # only applies when no 1 present
    out = run(x).strip()
    if out != '-1':
        n = len(a)
        val = int(out)
        assert n <= val <= 2 * n - 2

def test_reverse_invariant(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    rev_input = f'{n}\n' + ' '.join(map(str, reversed(a)))
    out1 = run(x).strip()
    out2 = run(rev_input).strip()
    assert out1 == out2

def test_append_one(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    new_n = n + 1
    new_a = a + [1]
    new_input = f'{new_n}\n' + ' '.join(map(str, new_a))
    out = run(new_input).strip()
    if out != '-1':
        non_one = sum(1 for v in new_a if v != 1)
        assert int(out) == non_one

def test_upper_bound_from_subarrays(run, x):
    import math
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    out = run(x).strip()
    if out == '-1':
        return
    ans = int(out)
    # compute all contiguous subarray gcds
    for i in range(n):
        g = 0
        for j in range(i, n):
            g = math.gcd(g, a[j])
            if g == 1:
                length = j - i + 1
                upper = n + length - 2
                assert ans <= upper

def test_lower_bound_from_ones_count(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    c = sum(1 for v in a if v == 1)
    out = run(x).strip()
    if out != '-1':
        assert int(out) >= len(a) - c

def test_single_element(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        a = int(lines[1])
        out = run(x).strip()
        if a == 1:
            assert out == '0'
        else:
            assert out == '-1'

