    orig_out = list(map(int, run(x).strip().split()))
    new_out = list(map(int, run(new_input).strip().split()))
    for s in range(1, n+1):
        if new_out[s-1] < orig_out[s-1]:
            raise AssertionError(f"Start {s}: time decreased after adding a candy")


def test_rotational_symmetry(run, x):
