    n, m = map(int, lines[0].split())
    candies = [tuple(map(int, line.split())) for line in lines[1:1+m]]
    # rotate all station numbers by +1 (mod n, 1‑based)
    new_candies = [((a % n) + 1, (b % n) + 1) for a, b in candies]
    new_input = f"{n} {m}\n" + '\n'.join(f'{a} {b}' for a, b in new_candies)
    orig_out = list(map(int, run(x).strip().split()))
