def test_adjacent_start_difference(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    out_vals = list(map(int, run(x).strip().split()))
    for s in range(1, n+1):
        next_s = (s % n) + 1
        diff = abs(out_vals[s-1] - out_vals[next_s-1])
        if diff > n:
            raise AssertionError(f"Difference between start {s} and {next_s} is {diff} > {n}")


def test_load_time_feasibility(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    candies = [tuple(map(int, line.split())) for line in lines[1:1+m]]
    out_vals = list(map(int, run(x).strip().split()))
    from collections import defaultdict
    # group candies by start station
    by_station = defaultdict(list)
    for a, b in candies:
        by_station[a].append(b)
    for s in range(1, n+1):
        T = out_vals[s-1]
        # For each station i, we need to assign distinct load times t = dist(s,i) + k*n
        # such that for each candy (i,b) we have t ≤ T - dist(i,b)
        for i in range(1, n+1):
            cands = by_station[i]
            if not cands:
                continue
            # possible load times for station i
            dist_si = (i - s) % n
            if dist_si == 0:
                dist_si = n
            # generate distinct t's up to T
            t0 = dist_si
            times = []
            while t0 <= T:
                times.append(t0)
                t0 += n
            # we need at least len(cands) distinct times
            if len(times) < len(cands):
                raise AssertionError(f"Start {s}: station {i} needs {len(cands)} load times, only {len(times)} possible")
            # sort required delivery deadlines
            deadlines = []
            for b in cands:
                dist_ib = (b - i) % n
                if dist_ib == 0:
                    dist_ib = n
                deadlines.append(T - dist_ib)
            deadlines.sort()
            # assign earliest possible load time to each candy (greedy)
            times_used = times[:len(cands)]
            for t, d in zip(times_used, deadlines):
                if t > d:
                    raise AssertionError(f"Start {s}: candy at station {i} cannot be loaded by time {t} (deadline {d})")


def test_upper_bound_round_robin(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    candies = [tuple(map(int, line.split())) for line in lines[1:1+m]]
    out_vals = list(map(int, run(x).strip().split()))
    # simulate round‑robin for each start s
    for s in range(1, n+1):
        # copy candies: each is (a,b, loaded?)
        state = [(a, b, False) for a, b in candies]
        pos = s
        time = 0
        delivered = 0
        # we'll stop after a generous limit to avoid infinite loop
        limit = 10 * n * m
        while delivered < m and time < limit:
            # load one candy if any at this station and not yet loaded
            load_candidate = None
            for idx, (a, b, loaded) in enumerate(state):
                if not loaded and a == pos:
                    load_candidate = idx
                    break
            if load_candidate is not None:
                a, b, _ = state[load_candidate]
                state[load_candidate] = (a, b, True)
            # deliver all loaded candies whose destination == pos
            for idx, (a, b, loaded) in enumerate(state):
                if loaded and b == pos:
                    # deliver
                    state[idx] = (a, b, False)  # mark as delivered (remove)
                    delivered += 1
            # move to next station
            pos = (pos % n) + 1
            time += 1
        U_s = time
        if out_vals[s-1] > U_s:
            raise AssertionError(f"Start {s}: output {out_vals[s-1]} exceeds simple upper bound {U_s}")


def test_lower_bound_load_only(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    candies = [tuple(map(int, line.split())) for line in lines[1:1+m]]
    from collections import defaultdict
    cnt = defaultdict(int)
    for a, b in candies:
        cnt[a] += 1
    out_vals = list(map(int, run(x).strip().split()))
    for s in range(1, n+1):
        R_s = 0
        for i in range(1, n+1):
            if cnt[i] == 0:
                continue
            dist_si = (i - s) % n
            if dist_si == 0:
                dist_si = n
            cand = dist_si + (cnt[i]-1)*n
            if cand > R_s:
                R_s = cand
        if out_vals[s-1] < R_s:
            raise AssertionError(f"Start {s}: output {out_vals[s-1]} < load‑only bound {R_s}")


def test_integer_nonnegative(run, x):
    # 10. Basic sanity: all output values integers and non‑negative.
    out = run(x).strip()
    if not out:
        raise AssertionError("Empty output")
    parts = out.split()
    for p in parts:
        if not p.lstrip('-').isdigit():
            raise AssertionError(f"Not an integer: {p}")
        val = int(p)
        if val < 0:
            raise AssertionError(f"Negative value: {val}")

