def test_output_format(run, x):
    out = run(x).strip().splitlines()
    if not out:
        return
    k = out[0].strip()
    assert k.isdigit()
    k = int(k)
    assert len(out) == k + 1
    seen = set()
    for line in out[1:]:
        s = line.strip()
        assert len(s) == 2 or len(s) == 3
        assert s not in seen
        seen.add(s)
    # lexicographical order
    for i in range(1, len(out)-1):
        assert out[i] <= out[i+1]


def test_substrings(run, x):
    out = run(x).strip().splitlines()
    if len(out) < 2:
        return
    s = x.strip()
    for line in out[1:]:
        suffix = line.strip()
        assert suffix in s


def test_start_position(run, x):
    out = run(x).strip().splitlines()
    if len(out) < 2:
        return
    s = x.strip()
    for line in out[1:]:
        suffix = line.strip()
        found = False
        l = len(suffix)
        for i in range(5, len(s) - l + 1):
            if s[i:i+l] == suffix:
                found = True
                break
        assert found, f"suffix {suffix} not found starting at position >=5"


def test_last_suffixes(run, x):
    s = x.strip()
    if len(s) < 7:
        return
    out = run(x).strip().splitlines()
    if len(out) < 2:
        return
    suffixes = set(out[1:])
    last_two = s[-2:]
    assert last_two in suffixes
    if len(s) >= 8:
        last_three = s[-3:]
        assert last_three in suffixes


def test_single_suffix_decomposition(run, x):
    s = x.strip()
    out = run(x).strip().splitlines()
    if len(out) < 2:
        return
    suffixes = set(out[1:])
    for i in range(5, len(s) - 1):
        l = len(s) - i
        if l == 2 or l == 3:
            assert s[i:] in suffixes


def test_two_suffix_decomposition_root5(run, x):
    s = x.strip()
    L = len(s) - 5
    out = run(x).strip().splitlines()
    if len(out) < 2:
        return
    suffixes = set(out[1:])
    if L == 4:
        if s[5:7] != s[7:9]:
            assert s[5:7] in suffixes
            assert s[7:9] in suffixes
    elif L == 5:
        assert s[5:7] in suffixes
        assert s[7:10] in suffixes
        assert s[5:8] in suffixes
        assert s[8:10] in suffixes
    elif L == 6:
        if s[5:8] != s[8:11]:
            assert s[5:8] in suffixes
            assert s[8:11] in suffixes


def test_metamorphic_append_two(run, x):
    s = x.strip()
    s2 = s + 'zz'
    # ensure length >=5
    assert len(s2) >= 5
    out = run(s2).strip().splitlines()
    if len(out) < 2:
        return
    suffixes = set(out[1:])
    assert 'zz' in suffixes


def test_metamorphic_append_three(run, x):
    s = x.strip()
    s3 = s + 'zzz'
    assert len(s3) >= 5
    out = run(s3).strip().splitlines()
    if len(out) < 2:
        return
    suffixes = set(out[1:])
    assert 'zzz' in suffixes


def test_bound_distinct_substrings(run, x):
    s = x.strip()
    out = run(x).strip().splitlines()
    if not out:
        return
    k = int(out[0].strip())
    possible = set()
    for i in range(5, len(s)):
        if i + 2 <= len(s):
            possible.add(s[i:i+2])
        if i + 3 <= len(s):
            possible.add(s[i:i+3])
    assert k <= len(possible)


def test_certificate_two_part(run, x):
    s = x.strip()
    out = run(x).strip().splitlines()
    if len(out) < 2:
        return
    suffixes = set(out[1:])
    n = len(s)
    for i in range(5, n - 3):
        # if remainder after taking two chars is 2, and next two are different
        if n - i - 2 == 2 and s[i:i+2] != s[i+2:i+4]:
            assert s[i:i+2] in suffixes
    for i in range(5, n - 4):
        if n - i - 2 == 3:
            assert s[i:i+2] in suffixes
    for i in range(5, n - 5):
        if n - i - 3 == 2:
            assert s[i:i+3] in suffixes
    for i in range(5, n - 5):
        if n - i - 3 == 3 and s[i:i+3] != s[i+3:i+6]:
            assert s[i:i+3] in suffixes

