def test_bruteforce_small(run, x):
    import sys
    N_str, K_str = x.strip().split()
    N = int(N_str)
    K = int(K_str)
    if N > 10:
        return
    from itertools import product
    MOD = 1_000_000_007
    all_perms = set()
    # each card 2..N: insertion choice front (0) or back (1)
    for insert_seq in product([0,1], repeat=N-1):
        # each removal step: front (0) or back (1)
        for remove_seq in product([0,1], repeat=N):
            dq = []
            # insert cards 1..N in order
            for card in range(1, N+1):
                if card == 1:
                    dq = [1]
                else:
                    if insert_seq[card-2] == 0:
                        dq.insert(0, card)
                    else:
                        dq.append(card)
            eaten = []
            # remove N times
            for r in remove_seq:
                if r == 0:
                    eaten.append(dq.pop(0))
                else:
                    eaten.append(dq.pop())
            # only consider sequences where dq ends empty (it always does)
            if not dq:
                all_perms.add(tuple(eaten))
    expected = sum(1 for perm in all_perms if perm[K-1] == 1)
    output = run(x).strip()
    got = int(output) if output.isdigit() else -1
    assert got == expected, f"Brute force: expected {expected}, got {got}"


def test_bounds(run, x):
    output = run(x).strip()
    val = int(output)
    assert 0 <= val <= 1_000_000_006, f"Output {val} out of mod range"


def test_modular(run, x):
    output = run(x).rstrip('\n')
    assert output.isdigit(), f"Output '{output}' is not an integer"
    val = int(output)
    MOD = 1_000_000_007
    assert 0 <= val < MOD, f"Output {val} not reduced modulo {MOD}"


def test_sum_total(run, x):
    import sys
    N_str, K_str = x.strip().split()
    N = int(N_str)
    K = int(K_str)
    if N > 10:
        return
    MOD = 1_000_000_007
    # compute total distinct permutations T by brute force (same as test 1)
    from itertools import product
    all_perms = set()
    for insert_seq in product([0,1], repeat=N-1):
        for remove_seq in product([0,1], repeat=N):
            dq = []
            for card in range(1, N+1):
                if card == 1:
                    dq = [1]
                else:
                    if insert_seq[card-2] == 0:
                        dq.insert(0, card)
                    else:
                        dq.append(card)
            eaten = []
            for r in remove_seq:
                if r == 0:
                    eaten.append(dq.pop(0))
                else:
                    eaten.append(dq.pop())
            if not dq:
                all_perms.add(tuple(eaten))
    T = len(all_perms) % MOD
    # sum ans_k for k=1..N
    total = 0
    for k in range(1, N+1):
        inp = f"{N} {k}\n"
        out = run(inp).strip()
        total = (total + int(out)) % MOD
    assert total == T, f"Sum over K = {total}, total distinct permutations = {T}"


def test_K1_formula(run, x):
    N_str, K_str = x.strip().split()
    N = int(N_str)
    K = int(K_str)
    if K != 1:
        return
    MOD = 1_000_000_007
    if N == 1:
        expected = 1
    else:
        expected = pow(2, N-2, MOD)
    output = run(x).strip()
    got = int(output)
    assert got == expected, f"K=1: expected {expected}, got {got}"


def test_symmetry_small(run, x):
    N_str, K_str = x.strip().split()
    N = int(N_str)
    K = int(K_str)
    if N > 10:
        return
    out1 = run(x).strip()
    out2 = run(f"{N} {N+1-K}\n").strip()
    assert out1 == out2, f"Symmetry broken for K={K} vs K={N+1-K}"


def test_N1(run, x):
    N_str, K_str = x.strip().split()
    N = int(N_str)
    K = int(K_str)
    if N != 1:
        return
    assert K == 1
    output = run(x)
    assert output == '1\n', f"For N=1 expected '1\\n', got {repr(output)}"


def test_N2(run, x):
    N_str, K_str = x.strip().split()
    N = int(N_str)
    if N != 2:
        return
    output = run(x).strip()
    val = int(output)
    assert val == 1, f"For N=2 expected 1, got {val}"


def test_N3(run, x):
    N_str, K_str = x.strip().split()
    N = int(N_str)
    if N != 3:
        return
    output = run(x).strip()
    val = int(output)
    assert val == 2, f"For N=3 expected 2, got {val}"


def test_ends_symmetry(run, x):
    N_str, K_str = x.strip().split()
    N = int(N_str)
    K = int(K_str)
    if K != 1 and K != N:
        return
    out1 = run(f"{N} 1\n").strip()
    out2 = run(f"{N} {N}\n").strip()
    assert out1 == out2, f"Ends symmetry broken for N={N}"

