{
  "rationale": "The tests are designed to catch deviations from the specification without computing the correct answer. They include bounds (non‑negativity, upper and lower combinatorial limits), structural invariants (output format, all‑governments and complete‑graph special cases), and metamorphic relations (vertex relabeling, disjoint union, adding an isolated node, adding a missing intra‑component edge). These properties follow directly from the problem statement: the answer is a count of edges that must respect simple‑graph limits, component‑wise feasibility, and symmetry under isomorphism. The weakest test is test_output_format because it only checks formatting, not the numerical answer; it would be the first to drop if space were needed.",
  "plan": [
    {
      "name": "test_non_negative",
      "intent": "The output must be a non‑negative integer because it counts added edges. Parse the output as an integer and assert it is greater than or equal to zero."
    },
    {
      "name": "test_upper_bound",
      "intent": "The output cannot exceed the maximum number of edges that can be added to a simple graph, which is n*(n‑1)/2 minus the existing edges m. Compute n and m from the input, compute this bound, and assert the output is less than or equal to it."
    },
    {
      "name": "test_lower_bound",
      "intent": "A feasible solution is to make each connected component of the input graph a complete graph without connecting different components. Therefore the answer must be at least the sum over each component of size*(size‑1)/2 minus m. Compute the component sizes from the input edges and assert the output is greater than or equal to that sum."
    },
    {
      "name": "test_vertex_relabeling",
      "intent": "The answer depends only on the graph structure, not on vertex labels. Apply a random permutation of vertex indices to the government list and edge list to obtain a relabeled input. Run the program on both the original and relabeled inputs and assert the outputs are equal."
    },
    {
      "name": "test_all_governments",
      "intent": "If every node is a government (k = n), no edge can be added because any edge would connect two governments. Check whether k equals n; if so, assert the output is exactly 0."
    },
    {
      "name": "test_complete_graph",
      "intent": "If the graph is already complete (m = n*(n‑1)/2), no edges can be added. Check whether m equals that value; if so, assert the output is exactly 0."
    },
    {
      "name": "test_disjoint_union",
      "intent": "Taking two disjoint copies of the input graph should double the answer. Construct a new input with vertex indices shifted for the second copy, doubling n, m, and k, and duplicating governments and edges. Run the program on this combined input and assert its output equals twice the output from the original."
    },
    {
      "name": "test_add_isolated_node",
      "intent": "Adding an isolated non‑government node cannot reduce the number of edges we can add, because we can ignore the new node. Construct a new input with n increased by 1, keeping m and k unchanged, and assert the new output is greater than or equal to the original output."
    },
    {
      "name": "test_add_edge_within_component",
      "intent": "If there exists a pair of nodes in the same connected component that are not already adjacent, adding an edge between them should reduce the answer by exactly 1, because the component remains the same and one missing edge is filled. Find such a pair if possible, construct the modified input, and assert the new output equals the original output minus 1. If no such pair exists, skip the assertion."
    },
    {
      "name": "test_output_format",
      "intent": "The output must be a single integer followed by a newline, with no extra whitespace. Check that the output string matches the regular pattern ^\\d+\\n$."
    }
  ]
}

