tests_src:
def test_length_one(run, x):
    n = int(x.strip().split('\n')[0])
    if n == 1:
        out = run(x).strip()
        assert out == '1', f'For N=1, output must be 1, got {out}'

def test_all_same(run, x):
    lines = x.strip().split('\n')
    s = lines[1]
    if len(set(s)) == 1:
        out = run(x).strip()
        assert out == '1', f'All same characters, output must be 1, got {out}'

def test_length_two_distinct(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1]
    if n == 2 and s[0] != s[1]:
        out = run(x).strip()
        assert out == '2', f'Length 2 distinct, output must be 2, got {out}'

def test_permutation_cycle(run, x):
    def permute(s, mapping):
        return ''.join(mapping[ch] for ch in s)
    mapping = {'A':'B', 'B':'C', 'C':'A'}
    lines = x.strip().split('\n')
    n = lines[0]
    s = lines[1]
    s2 = permute(s, mapping)
    x2 = f'{n}\n{s2}\n'
    out1 = run(x).strip()
    out2 = run(x2).strip()
    assert out1 == out2, f'Cyclic permutation must give same output, got {out1} vs {out2}'

def test_permutation_swap(run, x):
    def permute(s, mapping):
        return ''.join(mapping[ch] for ch in s)
    mapping = {'A':'B', 'B':'A', 'C':'C'}
    lines = x.strip().split('\n')
    n = lines[0]
    s = lines[1]
    s2 = permute(s, mapping)
    x2 = f'{n}\n{s2}\n'
    out1 = run(x).strip()
    out2 = run(x2).strip()
    assert out1 == out2, f'Swap A,B permutation must give same output, got {out1} vs {out2}'

def test_output_format(run, x):
    out = run(x).strip()
    # Must be a single integer
    val = int(out)
    # Must be between 0 and MOD-1 inclusive
    MOD = 10**9 + 7
    assert 0 <= val < MOD, f'Output {val} out of modulo range [0, {MOD-1}]'

def test_length_three_all_distinct(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1]
    if n == 3 and len(set(s)) == 3:
        out = run(x).strip()
        assert out == '3', f'Length 3 all distinct letters, output must be 3, got {out}'

def test_length_three_adjacent_pair(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1]
    if n == 3:
        cond = (s[0]==s[1] and s[1]!=s[2]) or (s[1]==s[2] and s[0]!=s[1])
        if cond:
            out = run(x).strip()
            assert out == '3', f'Length 3 adjacent pair, output must be 3, got {out}'

def test_length_three_alternating(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1]
    if n == 3 and s[0] == s[2] and s[0] != s[1]:
        out = run(x).strip()
        assert out == '4', f'Length 3 alternating (ABA style), output must be 4, got {out}'

def test_sample(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1]
    if n == 5 and s == 'ABAAC':
        out = run(x).strip()
        assert out == '11', f'Sample input ABAAC must output 11, got {out}'

