def test_symmetry(run, x):
    n, m = map(int, x.strip().split())
    out1 = run(x).strip()
    out2 = run(f'{m} {n}\n').strip()
    assert out1 == out2, f'Symmetry broken: ({n},{m}) -> {out1}, swapped -> {out2}'

def test_bounds(run, x):
    n, m = map(int, x.strip().split())
    ans = int(run(x).strip())
    total_pairs = n * m
    max_distinct = 5040  # 7!
    assert 0 <= ans <= min(total_pairs, max_distinct), f'ans={ans} outside [0, min({total_pairs}, 5040)]'

def test_digit_length_condition(run, x):
    n, m = map(int, x.strip().split())
    def digits_needed(val):
        if val <= 1:
            return 1
        a = 1
        while 7 ** a < val:
            a += 1
        return a
    a = digits_needed(n)
    b = digits_needed(m)
    ans = int(run(x).strip())
    if a + b > 7:
        assert ans == 0, f'a+b={a}+{b}>7 but ans={ans} != 0'

def test_small_case_formula(run, x):
    n, m = map(int, x.strip().split())
    if n <= 7 and m <= 7:
        ans = int(run(x).strip())
        expected = n * m - min(n, m)
        assert ans == expected, f'For n,m≤7 expected {expected}, got {ans}'

def test_permutation_count_bound(run, x):
    n, m = map(int, x.strip().split())
    def digits_needed(val):
        if val <= 1:
            return 1
        a = 1
        while 7 ** a < val:
            a += 1
        return a
    a = digits_needed(n)
    b = digits_needed(m)
    ans = int(run(x).strip())
    if a + b <= 7:
        import math
        P = math.perm(7, a + b)
        assert ans <= P, f'a+b={a}+{b}≤7 but ans={ans} > {P}=7!/(7-{a+b})!'

def test_non_zero_implies_length(run, x):
    n, m = map(int, x.strip().split())
    def digits_needed(val):
        if val <= 1:
            return 1
        a = 1
        while 7 ** a < val:
            a += 1
        return a
    a = digits_needed(n)
    b = digits_needed(m)
    ans = int(run(x).strip())
    if ans > 0:
        assert a + b <= 7, f'ans={ans}>0 but a+b={a}+{b}>7'

def test_output_format(run, x):
    output = run(x)
    assert output.endswith('\n'), 'Missing newline'
    s = output.strip()
    assert s.isdigit(), 'Output is not a non‑negative integer'
    assert int(s) >= 0, 'Negative integer'
    # No extra whitespace
    lines = output.splitlines()
    assert len(lines) == 1, 'More than one line'

def test_monotonic_n(run, x):
    n, m = map(int, x.strip().split())
    def digits_needed(val):
        if val <= 1:
            return 1
        a = 1
        while 7 ** a < val:
            a += 1
        return a
    a = digits_needed(n)
    if n > 1 and digits_needed(n - 1) == a:
        ans_nm = int(run(x).strip())
        ans_prev = int(run(f'{n-1} {m}\n').strip())
        assert ans_nm >= ans_prev, f'Increasing n from {n-1} to {n} decreased answer {ans_prev} -> {ans_nm}'

def test_monotonic_m(run, x):
    n, m = map(int, x.strip().split())
    def digits_needed(val):
        if val <= 1:
            return 1
        a = 1
        while 7 ** a < val:
            a += 1
        return a
    b = digits_needed(m)
    if m > 1 and digits_needed(m - 1) == b:
        ans_nm = int(run(x).strip())
        ans_prev = int(run(f'{n} {m-1}\n').strip())
        assert ans_nm >= ans_prev, f'Increasing m from {m-1} to {m} decreased answer {ans_prev} -> {ans_nm}'

def test_full_verification(run, x):
    n, m = map(int, x.strip().split())
    def digits_needed(val):
        if val <= 1:
            return 1
        a = 1
        while 7 ** a < val:
            a += 1
        return a
    a = digits_needed(n)
    b = digits_needed(m)
    ans = int(run(x).strip())
    if a + b > 7:
        assert ans == 0
        return
    # Enumerating all permutations of length a+b from digits 0..6 is only feasible when a+b small.
    # But a+b ≤ 7, so at most 7! = 5040 permutations, which is fine.
    # However, for large n or m we must interpret base‑7 numbers; that's just arithmetic.
    import itertools, math
    total = 0
    digits = list(range(7))
    for perm in itertools.permutations(digits, a + b):
        hour = 0
        for d in perm[:a]:
            hour = hour * 7 + d
        minute = 0
        for d in perm[a:]:
            minute = minute * 7 + d
        if hour < n and minute < m:
            total += 1
    assert ans == total, f'Expected {total}, got {ans}'

