def test_bounds(run, x):
    out = run(x).strip()
    # must be an integer
    try:
        d = int(out)
    except ValueError:
        raise AssertionError('output not an integer')
    # parse input to get Ciel strengths sum
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    ciel_start = 1 + n  # after Jiro's cards
    ciel_strengths = []
    for i in range(ciel_start, len(lines)):
        if lines[i].strip() == '':
            continue
        ciel_strengths.append(int(lines[i].strip()))
    total_ciel = sum(ciel_strengths)
    # damage must be between 0 and total_ciel inclusive
    if d < 0 or d > total_ciel:
        raise AssertionError(f'damage {d} outside [0, {total_ciel}]')

