def test_scaling(run, x):
    # only apply if all strengths <= 4000 (so doubling stays <= 8000)
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    strengths = []
    for i in range(1, 1 + n):
        parts = lines[i].split()
        strengths.append(int(parts[1]))
    for i in range(1 + n, len(lines)):
        if lines[i].strip() == '':
            continue
        strengths.append(int(lines[i].strip()))
    if any(s > 4000 for s in strengths):
        return  # skip, scaling would exceed allowed max
    orig_out = run(x).strip()
    try:
        d1 = int(orig_out)
    except ValueError:
        raise AssertionError('original output not integer')
    # double all strengths
    new_lines = []
    new_lines.append(f'{n} {m}')
    for i in range(1, 1 + n):
        parts = lines[i].split()
        pos, strn = parts[0], int(parts[1])
        new_lines.append(f'{pos} {strn*2}')
    for i in range(1 + n, len(lines)):
        if lines[i].strip() == '':
            continue
        strn = int(lines[i].strip())
        new_lines.append(str(strn*2))
    doubled_input = '\n'.join(new_lines)
    doubled_out = run(doubled_input).strip()
    try:
        d2 = int(doubled_out)
    except ValueError:
        raise AssertionError('doubled output not integer')
    if d2 != 2 * d1:
        raise AssertionError(f'scaling failed: {d1} vs {d2} (expected double)')

