def test_N_equals_2_formula(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N != 2:
        return
    A = list(map(int, lines[1].split()))
    a1, a2 = A
    MOD = 1000000007
    def modinv(a):
        return pow(a, MOD-2, MOD)
    good = 0
    for x1 in range(1, a1+1):
        good += max(0, a2 - x1)  # x2 > x1, x2 from 1..a2
    total = a1 * a2 + good  # 1 for every pair, plus extra 1 for each increasing pair
    expected = (total * modinv(a1 * a2)) % MOD
    output = run(x).strip()
    assert int(output) == expected

