def test_monotonicity(run, x):
    MOD = 1000000007
    def modinv(a):
        return pow(a, MOD-2, MOD)
    def brute_expectation(N, A):
        prod = 1
        for a in A:
            prod *= a
        from itertools import product
        total = 0
        for xs in product(*[range(1, a+1) for a in A]):
            dp = []
            for v in xs:
                from bisect import bisect_left
                pos = bisect_left(dp, v)
                if pos == len(dp):
                    dp.append(v)
                else:
                    dp[pos] = v
            total += len(dp)
        return (total * modinv(prod)) % MOD
    lines = x.strip().split('\n')
    N = int(lines[0])
    A = list(map(int, lines[1].split()))
    prod = 1
    for a in A:
        if prod > 10**6:
            return
        prod *= a
    if prod > 10**6:
        return
    orig = brute_expectation(N, A)
    for i in range(N):
        if A[i] < 10**9:
            B = A.copy()
            B[i] += 1
            prod2 = prod * ((A[i]+1)//A[i])
            if prod2 <= 10**6:
                new = brute_expectation(N, B)
                assert new >= orig

def test_all_equal_small(run, x):
    MOD = 1000000007
    def modinv(a):
        return pow(a, MOD-2, MOD)
    lines = x.strip().split('\n')
    N = int(lines[0])
    A = list(map(int, lines[1].split()))
    if len(set(A)) != 1:
        return
    M = A[0]
    if M > 10:
        return
    prod = M ** N
    if prod > 10**6:
        return
    from itertools import product
    total = 0
    for xs in product(range(1, M+1), repeat=N):
        dp = []
        for v in xs:
            from bisect import bisect_left
            pos = bisect_left(dp, v)
            if pos == len(dp):
                dp.append(v)
            else:
                dp[pos] = v
        total += len(dp)
    expected = (total * modinv(prod)) % MOD
    output = run(x).strip()
    assert int(output) == expected

