def test_output_format(run, x):
    out = run(x).strip()
    parts = out.split()
    assert len(parts) == 3, "output must have exactly three numbers"
    for p in parts:
        assert p.isdigit() or (p[0]=='-' and p[1:].isdigit()), "non‑integer output"
    # no extra characters after the third number
    # split on whitespace, then reconstruct
    reconstructed = ' '.join(parts)
    assert out == reconstructed, "extra whitespace or newlines"

