def test_scaling_double(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    # Check if scaling by 2 keeps all values within [-10^9, 10^9]
    if all(-10**9 <= 2*x <= 10**9 for x in a):
        scaled_a = [ 2*x for x in a ]
        scaled_input = f'{n}\n' + ' '.join(map(str, scaled_a)) + '\n'
        out1 = int(run(x).strip())
        out2 = int(run(scaled_input).strip())
        assert out2 == 2 * out1, f'Scaling by 2 should double the answer: {out1} -> {out2}'

def test_brute_force_small_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n <= 10:
        best = -10**18
        for l in range(n):
            for r in range(l+1, n):
                s = 0
                for i in range(l, r):
                    term = abs(a[i] - a[i+1]) * ((-1) ** (i - l))
                    s += term
                if s > best:
                    best = s
        out = int(run(x).strip())
        assert out == best, f'Brute‑force maximum for n={n} is {best}, got {out}'

