tests_src:
def test_symmetry(run, x):
    K, N = map(int, x.strip().split())
    out = run(x).strip().split()
    assert len(out) == 2 * K - 1
    for t in range(2 * K - 1):
        assert int(out[t]) == int(out[2 * K - 2 - t]), f'symmetry violated at i={t+2}'

def test_length(run, x):
    K, N = map(int, x.strip().split())
    out_lines = run(x).strip().split('\n')
    assert len(out_lines) == 2 * K - 1, f'expected {2*K-1} lines, got {len(out_lines)}'

def test_range(run, x):
    out_lines = run(x).strip().split('\n')
    for line in out_lines:
        val = int(line)
        assert 0 <= val < 998244353, f'value {val} out of modulus range'

def test_sample(run, x):
    if x == '3 3\n':
        out = run(x)
        assert out == '7\n7\n4\n7\n7\n', f'sample mismatch'

def test_brute_small(run, x):
    import math
    K, N = map(int, x.strip().split())
    total_multisets = math.comb(N + K - 1, K - 1)
    if total_multisets > 200000:
        return  # skip, too large
    # enumerate all multisets via stars-and-bars
    from itertools import combinations_with_replacement
    multisets = combinations_with_replacement(range(1, K + 1), N)
    # count for each i
    expected = [0] * (2 * K + 1)  # indices 0..2K
    for m in multisets:
        forbidden_sums = set()
        for a in range(N):
            for b in range(a + 1, N):
                s = m[a] + m[b]
                if 2 <= s <= 2 * K:
                    forbidden_sums.add(s)
        for s in range(2, 2 * K + 1):
            if s not in forbidden_sums:
                expected[s] += 1
    out = list(map(int, run(x).strip().split()))
    for idx, val in enumerate(out, start=2):
        assert val % 998244353 == expected[idx] % 998244353, f'mismatch at i={idx}'

def test_i2(run, x):
    import math
    K, N = map(int, x.strip().split())
    if K == 1:
        expected = 0
    else:
        # C(N+K-2, K-2) + C(N+K-3, K-2)
        mod = 998244353
        a = math.comb(N + K - 2, K - 2) % mod
        b = math.comb(N + K - 3, K - 2) % mod
        expected = (a + b) % mod
    out = list(map(int, run(x).strip().split()))
    assert out[0] == expected, f'i=2 expected {expected}, got {out[0]}'

def test_i2K(run, x):
    import math
    K, N = map(int, x.strip().split())
    if K == 1:
        expected = 0
    else:
        mod = 998244353
        a = math.comb(N + K - 2, K - 2) % mod
        b = math.comb(N + K - 3, K - 2) % mod
        expected = (a + b) % mod
    out = list(map(int, run(x).strip().split()))
    assert out[-1] == expected, f'i=2K expected {expected}, got {out[-1]}'

def test_positivity(run, x):
    K, N = map(int, x.strip().split())
    if K >= 2:
        out = list(map(int, run(x).strip().split()))
        assert out[0] > 0, f'first output (i=2) should be positive for K≥2'

def test_K1(run, x):
    K, N = map(int, x.strip().split())
    if K == 1:
        out = run(x).strip()
        assert out == '0', f'for K=1 output must be "0", got {repr(out)}'

def test_K2(run, x):
    K, N = map(int, x.strip().split())
    if K == 2:
